      "Mise en température",
      "Pour les macarons congelés uniquement : sortez les boîtes du congélateur la veille au soir et entreposez-les au réfrigérateur en gardant le film alimentaire. Le lendemain, les macarons sont prêts à être vendus et consommés.",
