      "Une fois décongelés, il est conseillé de vendre les macarons dans les 48 heures. Pour les macarons stockés en froid positif, on peut les vendre jusqu’à 6 jours après la mise en boite.",
      "Conseil de consommation",
      "Sortez les macarons du réfrigérateur deux heures avant consommation.",
